import { FoodCard } from "canteen";

/*
  Content is the real thing: dishes, descriptions and plate photographs taken
  from production. The Norwegian flavour text is the point of this component —
  a card previewed with "Lorem ipsum" would misrepresent what it is for, and
  the design agent imitates whatever it sees here.
*/

/*
  The plates are inlined as data URIs rather than pointed at Supabase.
  The remote URL loads fine in a browser, but the capture screenshots the
  card before it arrives, and a preview of this component with no food in it
  misrepresents the one thing it exists to show. Inlining also means the card
  renders the same wherever it is opened, with no dependency on a CDN the
  design tool may not be able to reach.

  340px WebP, the width a phone card actually requests.
*/
const TANDOORI = "data:image/webp;base64,";
const TORSK = "data:image/webp;base64,";
const BEAN = "data:image/webp;base64,";

const noop = () => {};

const base = {
  cardIdx: 0,
  selectedDay: 0,
  todayIndex: 0,
  voteCount: 0,
  maxVotes: 0,
  onImageClick: noop,
  onCardClick: noop,
};

const tandoori = {
  canteenName: "Eat the street",
  canteen: { week: "Uke/week 37", openingHours: "10:30 - 14:00" },
  mainDish: {
    dish: "Tandoori kyllinglår med ris og saus",
    allergens: [{ id: "7", name: "Milk" }],
    isMain: true,
  },
  sideDishes: [
    { dish: "Pad Thai med grønnsaker", allergens: [{ id: "1", name: "Egg" }, { id: "3", name: "Gluten" }], isMain: false },
    { dish: "Kikertsuppe med urter", allergens: [], isMain: false },
    { dish: "Pizza med salami og rucola", allergens: [{ id: "3", name: "Gluten" }, { id: "7", name: "Milk" }], isMain: false },
  ],
  mainAllergens: [{ id: "7", name: "Milk" }],
  description:
    "Kyllinglår med nok krydder til å vekke selv den mest trøtte kontorrotte, servert med ris som tar imot sausen.",
  origin: { code: "in", country: "India" },
  imagePath: TANDOORI,
  availabilityNotes: ["Halal tilgjengelig"],
};

const torsk = {
  canteenName: "Fresh4you",
  canteen: { week: "Uke/week 37", openingHours: "10:30 - 13:00" },
  mainDish: {
    dish: "Ovnsbakt torskefilet med rattatouille og saltbakte poteter",
    allergens: [{ id: "2", name: "Fish" }],
    isMain: true,
  },
  sideDishes: [
    { dish: "Stekt ris med egg og grønnsaker", allergens: [{ id: "1", name: "Egg" }], isMain: false },
    { dish: "Norsk bondesuppe med urøkt pølse", allergens: [{ id: "9", name: "Celery" }], isMain: false },
  ],
  mainAllergens: [{ id: "2", name: "Fish" }],
  description:
    "Torsk som smelter på tungen, med grønnsaker som har sett bedre dager men fortsatt gjør jobben.",
  origin: { code: "no", country: "Norway" },
  imagePath: TORSK,
};

/** The default card: a published menu for today. */
export const Default = () => <FoodCard {...base} data={tandoori} />;

/** A second canteen, to show the row is not one repeated card. */
export const WithFishAllergen = () => <FoodCard {...base} data={torsk} cardIdx={1} />;

/**
 * The winning card. `voteCount === maxVotes` and both above zero is what
 * raises the leader pip — the two props are read together, never alone.
 */
export const Leading = () => (
  <FoodCard {...base} data={tandoori} voteCount={7} maxVotes={7} />
);

/**
 * A kitchen that has not published this week yet, so last week's menu is shown
 * with the week it belongs to. The card recedes rather than disappearing:
 * a stale menu is more useful than a hole in the row.
 */
export const Outdated = () => (
  <FoodCard
    {...base}
    data={{
      ...torsk,
      canteenName: "Kantine M",
      canteen: { week: "Bygg / Building M - Uke/Week 36", openingHours: "10:30 - 13:00" },
      mainDish: { dish: "Bean stew with pork and rice", allergens: [], isMain: true },
      sideDishes: [],
      mainAllergens: [],
      description: "En solid gryte som er langt mer spennende enn navnet antyder.",
      origin: { code: "br", country: "Brazil" },
      imagePath: BEAN,
      isOutdated: true,
      canteenWeekNum: 36,
    }}
    cardIdx={2}
  />
);

/**
 * The weekend state. `todayIndex: -1` means no day is "today", and the card
 * drops its voting affordance on its own rather than needing to be told.
 */
export const WeekendNoVoting = () => (
  <FoodCard {...base} data={tandoori} todayIndex={-1} />
);
